mapper.select:
select *
from order_info
where `status` = #{status}
  and tx_status = #{txStatus}
limit 50

select *
from order_info
where `status` = #{status}
  and refund_tx_status = #{txStatus}
limit 50

select info.*
from order_info info
left join goods_spu spu on spu.goods_id = info.goods_id
left join goods_sku sku on sku.sku_id = info.sku_id


        and info.seller_address = #{sellerAddress}


        and info.buyer_address = #{buyerAddress}


        and info.`status` = #{status}


        and info.tx_status = #{txStatus}


        and info.delete_status = #{deleteStatus}


        and (
        info.order_id = #{vague}
        or info.seller_address = #{vague}
        or info.buyer_address = #{vague}
        or info.goods_id = #{vague}
        or info.sku_id = #{vague}
        or info.pay_hash = #{vague}
        or info.tx_hash = #{vague}
        or info.refund_apply_tx_hash = #{vague}
        or info.refund_tx_hash = #{vague}
        or spu.name like CONCAT('%', #{vague}, '%')
        or sku.name like CONCAT('%', #{vague}, '%')
        or sku.token_name like CONCAT('%', #{vague}, '%')
        )


order by info.order_id desc
